<?php
declare(strict_types=1);require_once dirname(__DIR__).'/config/bootstrap.php';require_permission('sales.view_details');$id=(int)($_GET['id']??0);$st=db()->prepare('SELECT s.*,c.name customer_name,c.phone customer_phone,u.full_name cashier,v.full_name voided_by_name FROM sales s LEFT JOIN customers c ON c.id=s.customer_id INNER JOIN users u ON u.id=s.created_by LEFT JOIN users v ON v.id=s.voided_by WHERE s.id=:id');$st->execute([':id'=>$id]);$s=$st->fetch();if(!$s){flash('error','Sale not found.');redirect('sales/index');}$it=db()->prepare('SELECT * FROM sale_items WHERE sale_id=:id ORDER BY id');$it->execute([':id'=>$id]);$items=$it->fetchAll();$pay=db()->prepare('SELECT sp.*,pm.name method_name,pm.method_type FROM sale_payments sp INNER JOIN payment_methods pm ON pm.id=sp.payment_method_id WHERE sp.sale_id=:id ORDER BY sp.id');$pay->execute([':id'=>$id]);$payments=$pay->fetchAll();$pageTitle=$s['sale_no'];$pageStyles=['admin.css','commerce.css'];require BASE_PATH.'/includes/header.php';require BASE_PATH.'/includes/sidebar.php';?>
<div class="app-main"><?php require BASE_PATH.'/includes/navbar.php';?><main class="content"><?php require BASE_PATH.'/includes/alerts.php';?><div class="page-toolbar"><div><a class="back-link" href="<?=e(app_url('sales/index'))?>">← Sales</a><h2><?=e($s['sale_no'])?></h2><p><?=e(format_datetime($s['sale_date']))?> · <?=e($s['cashier'])?></p></div><div class="toolbar-actions"><?php if($s['status']==='completed'):?><a class="button button--secondary" href="<?=e(app_url('pos/receipt?id='.$id))?>">Receipt</a><?php endif;?><?php if($s['status']==='completed'&&user_can('pos.void')):?><a class="button button--danger" href="<?=e(app_url('sales/void?id='.$id))?>">Void sale</a><?php endif;?></div></div>
<?php if($s['status']==='voided'):?><div class="app-alert app-alert--danger">This sale was voided <?=e(format_datetime($s['voided_at']))?> by <?=e($s['voided_by_name']?:'a user')?>. Reason: <?=e($s['void_reason']?:'Not stated')?></div><?php endif;?>
<section class="mini-metric-grid"><article class="mini-metric"><span>Sale total</span><strong><?=e(money($s['total_amount']))?></strong></article><article class="mini-metric"><span>COGS</span><strong><?=e(money($s['cogs_amount']))?></strong></article><article class="mini-metric"><span>Gross profit</span><strong><?=e(money($s['gross_profit']))?></strong></article><article class="mini-metric"><span>Outstanding</span><strong><?=e(money($s['balance_due']))?></strong></article></section>
<section class="panel-card table-panel"><div class="panel-card__header"><h3>Sale items</h3></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Product</th><th>Quantity</th><th>Price</th><th>Discount</th><th>Total</th><th>Cost</th><th>Profit</th></tr></thead><tbody><?php foreach($items as$i):?><tr><td><strong><?=e($i['product_name_snapshot'])?></strong><small class="table-note"><?=e($i['sku_snapshot'])?></small></td><td><?=e(format_quantity($i['quantity']))?> <?=e($i['unit_snapshot'])?></td><td><?=e(money($i['unit_price']))?></td><td><?=e(money($i['discount_amount']))?></td><td><?=e(money($i['line_total']))?></td><td><?=e(money($i['cogs_amount']))?></td><td><?=e(money($i['profit_amount']))?></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="detail-two-column section-gap"><article class="panel-card"><div class="panel-card__header"><h3>Payment breakdown</h3></div><div class="simple-list"><?php foreach($payments as$p):?><div class="simple-list__row"><div><strong><?=e($p['method_name'])?></strong><span><?=e($p['reference_no']?:format_datetime($p['paid_at']))?></span></div><b><?=e(money($p['amount']))?></b></div><?php endforeach;?></div></article><article class="panel-card detail-card"><div class="panel-card__header"><h3>Sale details</h3></div><dl class="detail-list"><div><dt>Customer</dt><dd><?=e($s['customer_name']?:'Walk-in customer')?></dd></div><div><dt>Status</dt><dd><?=e(ucfirst($s['status']))?></dd></div><div><dt>Payment status</dt><dd><?=e(ucfirst($s['payment_status']))?></dd></div><div><dt>Notes</dt><dd><?=e($s['notes']?:'—')?></dd></div></dl></article></section>
</main></div><?php require BASE_PATH.'/includes/footer.php';?>
